{\n        const metadata = await message.groupMetadata(message.jid)\n        const admins = metadata.participants\n          .filter(p => p.admin === 'admin' || p.admin === 'superadmin')\n          .map(p => p.id)\n\n        if (participants.some(p => admins.includes(p))) {\n          await message.groupParticipantsUpdate(message.jid, [actor], 'demote')\n        }\n      }\n    } catch (e) {\n      console.log('AntiMod Error:', e)\n    }\n  }\n)\n\n// ================= GROUP NAME CHANGE =================\nbot(\n  {\n    on: 'groups.update'\n  },\n  async (message) => {\n    try {\n      const data = await load()\n      if (!data.enabled) return\n\n      const update = Array.isArray(message) ? message[0] : message\n      if (!update || !update.id || !update.subject) return\n\n      const jid = update.id\n      const newName = update.subject\n      const actor = update.author || update.participant\n\n      const botNumber = message?.client?.user?.id\n      if (actor && botNumber && actor === botNumber) return\n\n      const oldName = data.groupNames[jid]\n\n      if (!oldName) {\n        data.groupNames[jid] = newName\n        await setData(DB_KEY, data)\n        return\n      }\n\n      if (newName !== oldName && actor) {\n        // Demote actor\n        await message.groupParticipantsUpdate(jid, [actor], 'demote')\n        // Restore name\n        await message.groupUpdateSubject(jid, oldName)\n      }\n    } catch (e) {\n      console.log('AntiMod Name Error:', e)\n    }\n  }\n)	group	𝐁я͂ɑɪ͜ƞ҃Ɩɛ͜𝐬𝐬̚ 𝐂σ͜͞ϻϻ̑ʋ͜ƞɪʈ͞ɣ ~ 💗🥂	2026-08-27T19:18:41.718Z	2026-08-27 20:18:41.718969+01
